.landing {
  max-width: 1040px;
  margin: 0 auto;
  padding: 80px 24px;
  display: flex;
  flex-direction: column;
  gap: 72px;
}

.landing h1,
.landing h2,
.landing p {
  margin: 0;
}

.landing__hero,
.landing__cta {
  display: flex;
  flex-direction: column;
